#include <stdio.h>
#include <string.h>
#include <stdbool.h>

bool isAnagram(const char* s, const char* t) {
    if (strlen(s) != strlen(t)) return false;
    int count[26] = {0};
    for (size_t i = 0; s[i] != '\0'; ++i) {
        ++count[s[i] - 'a'];
    }
    for (size_t i = 0; t[i] != '\0'; ++i) {
        int idx = t[i] - 'a';
        if (--count[idx] < 0) return false;
    }
    return true;
}

int main(void) {
    char line[100020];
    char s[50001], t[50001];
    if (!fgets(line, sizeof(line), stdin)) return 1;
    if (sscanf(line, " [ \"%50000[^\"]\" , \"%50000[^\"]\" ]", s, t) != 2) return 1;
    printf("%s\n", isAnagram(s, t) ? "true" : "false");
    return 0;
}

