using namespace std;

class Solution {
public:
    bool isAnagram(const string& s, const string& t) {
        if (s.size() != t.size()) return false;
        int count[26] = {};
        for (char ch : s) {
            ++count[ch - 'a'];
        }
        for (char ch : t) {
            int idx = ch - 'a';
            if (--count[idx] < 0) return false;
        }
        return true;
    }
};

int main() {
    string line;
    getline(cin, line);
    vector<string> values;
    for (size_t pos = 0; pos < line.size() && values.size() < 2; ) {
        size_t open = line.find('"', pos);
        if (open == string::npos) break;
        size_t close = line.find('"', open + 1);
        if (close == string::npos) break;
        values.push_back(line.substr(open + 1, close - open - 1));
        pos = close + 1;
    }
    if (values.size() != 2) return 1;
    cout << (Solution().isAnagram(values[0], values[1]) ? "true" : "false") << '\n';
    return 0;
}

