import java.io.*;
import java.util.*;

class Solution {
    public boolean isAnagram(String s, String t) {
        if (s.length() != t.length()) return false;
        int[] count = new int[26];
        for (int i = 0; i < s.length(); i++) {
            count[s.charAt(i) - 'a']++;
        }
        for (int i = 0; i < t.length(); i++) {
            int idx = t.charAt(i) - 'a';
            if (--count[idx] < 0) return false;
        }
        return true;
    }
}

public class Main {
    private static String[] parseTwoStrings(String line) {
        ArrayList<String> out = new ArrayList<>(2);
        int i = 0;
        while (i < line.length() && out.size() < 2) {
            int open = line.indexOf('"', i);
            if (open < 0) break;
            int close = line.indexOf('"', open + 1);
            if (close < 0) break;
            out.add(line.substring(open + 1, close));
            i = close + 1;
        }
        if (out.size() != 2) throw new IllegalArgumentException("Invalid input");
        return new String[]{out.get(0), out.get(1)};
    }

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line = br.readLine();
        String[] values = parseTwoStrings(line);
        System.out.println(new Solution().isAnagram(values[0], values[1]));
    }
}

